CREATE TABLE IF NOT EXISTS press_db.hyb_employee_attendance
(
    attendance_id bigserial NOT NULL,
    employee_id bigint NOT NULL,
    department_id bigint,
    shift_type_id integer,
    attendance_date date NOT NULL,
    check_in timestamp without time zone,
    check_out timestamp without time zone,
    break_minutes integer DEFAULT 0,
    total_hours numeric(5, 2) GENERATED ALWAYS AS (
CASE
    WHEN ((check_in IS NOT NULL) AND (check_out IS NOT NULL)) THEN ((EXTRACT(epoch FROM (check_out - check_in)) / 3600.0) - ((break_minutes)::numeric / 60.0))
    ELSE (0)::numeric
END) STORED,
    status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'PRESENT'::character varying,
    overtime_hours numeric(5, 2) DEFAULT 0,
    overtime_approved boolean DEFAULT false,
    job_id bigint,
    process_id integer,
    machine_id bigint,
    attendance_data jsonb DEFAULT '{}'::jsonb,
    remarks text COLLATE pg_catalog."default",
    created_on timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT hyb_employee_attendance_pkey PRIMARY KEY (attendance_id),
    CONSTRAINT uq_att_employee_date UNIQUE (employee_id, attendance_date)
);

COMMENT ON TABLE press_db.hyb_employee_attendance
    IS 'Employee attendance and shift tracking for production floor. Links to job/process for labour cost allocation.';

CREATE TABLE IF NOT EXISTS press_db.hyb_job_rate_calculator
(
    rate_calc_id bigserial NOT NULL,
    calc_ref_no character varying(50) COLLATE pg_catalog."default" NOT NULL,
    enquiry_id bigint,
    quotation_id bigint,
    job_id bigint,
    party_id integer,
    job_type_id integer,
    product_type_id integer,
    product_size_id integer,
    quantity integer NOT NULL DEFAULT 0,
    total_pages integer NOT NULL DEFAULT 0,
    trim_width_mm numeric(8, 2),
    trim_height_mm numeric(8, 2),
    printing_mode character varying(30) COLLATE pg_catalog."default",
    is_customer_material boolean DEFAULT false,
    grand_total numeric(14, 2) NOT NULL DEFAULT 0,
    tax_amount numeric(14, 2) NOT NULL DEFAULT 0,
    net_total numeric(14, 2) NOT NULL DEFAULT 0,
    cost_per_unit numeric(14, 4) NOT NULL DEFAULT 0,
    parts_data jsonb DEFAULT '[]'::jsonb,
    cost_breakdown jsonb DEFAULT '[]'::jsonb,
    bom_data jsonb DEFAULT '[]'::jsonb,
    ai_insights jsonb DEFAULT '[]'::jsonb,
    recommended_machines jsonb DEFAULT '[]'::jsonb,
    calc_input_snapshot jsonb DEFAULT '{}'::jsonb,
    status character varying(30) COLLATE pg_catalog."default" NOT NULL DEFAULT 'DRAFT'::character varying,
    validity_date date,
    version integer NOT NULL DEFAULT 1,
    parent_calc_id bigint,
    internal_remarks text COLLATE pg_catalog."default",
    client_remarks text COLLATE pg_catalog."default",
    created_by bigint NOT NULL,
    created_on timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_by character varying(50) COLLATE pg_catalog."default",
    modified_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT hyb_job_rate_calculator_pkey PRIMARY KEY (rate_calc_id)
);

COMMENT ON TABLE press_db.hyb_job_rate_calculator
    IS 'Hybrid SQL+JSONB table storing AI Rate Calculator results. Relational columns for product config, IDs, totals (joins/filters/reporting). JSONB columns for parts, cost breakdown, BOM, AI insights, machine recommendations, and full input snapshot. Links to enquiry received process for quotation and negotiation workflow.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.calc_ref_no
    IS 'Unique reference number generated as RC-YYYYMMDD-HHMMSS.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.parts_data
    IS 'JSONB array of product parts with per-part configuration (pages, copies, colors, paper, finishing) and calculated results (sheets, paper cost, plate cost, ink cost, finishing cost, sub-total).';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.cost_breakdown
    IS 'JSONB array of cost line items displayed in the Cost Breakdown table. Each item has icon, name, category, detail, and amount.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.bom_data
    IS 'JSONB array of Bill of Materials line items. Each item has category, material_name, specification, for_part, quantity, unit, rate, and amount.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.ai_insights
    IS 'JSONB array of AI-generated insights/recommendations. Each has icon, title, description, and severity (info/warn/error).';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.recommended_machines
    IS 'JSONB array of machine options with estimated costs for comparison.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.calc_input_snapshot
    IS 'JSONB snapshot of all selected master data at calculation time for reproducibility and audit trail.';

COMMENT ON COLUMN press_db.hyb_job_rate_calculator.parent_calc_id
    IS 'Self-referencing FK to previous version when a rate calculation is revised.';

