    isfinancial boolean,
    issystemapproval boolean,
    ismandatory boolean,
    isactive boolean,
    createdby character varying(50) COLLATE pg_catalog."default",
    createdon timestamp without time zone,
    CONSTRAINT mst_approval_type_pkey PRIMARY KEY (approvaltypeid)
);

CREATE TABLE IF NOT EXISTS press_db.mst_bank_account
(
    bank_account_id serial NOT NULL,
    account_code character varying(30) COLLATE pg_catalog."default" NOT NULL,
    account_name character varying(200) COLLATE pg_catalog."default" NOT NULL,
    company_id integer NOT NULL,
    location_id integer,
    account_no character varying(50) COLLATE pg_catalog."default" NOT NULL,
    bank_name character varying(150) COLLATE pg_catalog."default" NOT NULL,
    branch_name character varying(150) COLLATE pg_catalog."default",
    ifsc_code character varying(20) COLLATE pg_catalog."default",
    micr_code character varying(20) COLLATE pg_catalog."default",
    swift_code character varying(20) COLLATE pg_catalog."default",
    account_type character varying(30) COLLATE pg_catalog."default" DEFAULT 'CURRENT'::character varying,
    currency_id integer,
    opening_balance numeric(18, 2) DEFAULT 0,
    current_balance numeric(18, 2) DEFAULT 0,
    last_reconciled_on date,
    last_reconciled_balance numeric(18, 2) DEFAULT 0,
    account_head_id bigint,
    is_default boolean DEFAULT false,
    is_active boolean DEFAULT true,
    remarks text COLLATE pg_catalog."default",
    created_by character varying(100) COLLATE pg_catalog."default",
    created_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    modified_by character varying(100) COLLATE pg_catalog."default",
    modified_on timestamp without time zone,
    CONSTRAINT mst_bank_account_pkey PRIMARY KEY (bank_account_id),
    CONSTRAINT uq_bank_account_code UNIQUE (account_code)
);

COMMENT ON TABLE press_db.mst_bank_account
    IS 'Company bank accounts used for bank receipt, bank payment and bank reconciliation.';

CREATE TABLE IF NOT EXISTS press_db.mst_binding
(
    binding_id bigserial NOT NULL,
    binding_code character varying(50) COLLATE pg_catalog."default" NOT NULL,
