CREATE TABLE IF NOT EXISTS press_db.mst_department
(
    dept_id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1001 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 ),
    dept_code character varying(20) COLLATE pg_catalog."default",
