CREATE TABLE IF NOT EXISTS press_db.mst_direction
(
    id serial NOT NULL,
    name character varying(100) COLLATE pg_catalog."default" NOT NULL,
    is_active boolean DEFAULT true,
    CONSTRAINT mst_direction_pkey PRIMARY KEY (id),
    CONSTRAINT uq_direction_name UNIQUE (name)
);

COMMENT ON TABLE press_db.mst_direction
    IS 'Lookup for tax/accounting flow direction. id=1 Output (Payable), id=2 Input (ITC). Referenced by trn_tax_ledger.direction.';

COMMENT ON COLUMN press_db.mst_direction.id
    IS 'Primary key. 1=Output Tax, 2=Input Tax — used directly as FK value in trn_tax_ledger.';

COMMENT ON COLUMN press_db.mst_direction.name
    IS 'Human-readable direction label.';

COMMENT ON COLUMN press_db.mst_direction.is_active
    IS 'TRUE = active.';

