COMMENT ON TABLE press_db.trn_journal_voucher_line
    IS 'Journal voucher debit/credit lines. Each line posts to one account head. Sum of debits must equal sum of credits within a journal.';

CREATE TABLE IF NOT EXISTS press_db.trn_ledger
(
    ledger_id bigserial NOT NULL,
    transaction_date date NOT NULL,
    account_head_id bigint NOT NULL,
    party_id integer,
    debit_amount numeric(18, 2) DEFAULT 0,
    credit_amount numeric(18, 2) DEFAULT 0,
    voucher_type_id integer,
    voucher_id bigint,
    voucher_no character varying(50) COLLATE pg_catalog."default",
    reference_no character varying(100) COLLATE pg_catalog."default",
    reference_date date,
    remarks text COLLATE pg_catalog."default",
    created_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT trn_ledger_pkey PRIMARY KEY (ledger_id)
);

CREATE TABLE IF NOT EXISTS press_db.trn_machine_breakdown
(
    breakdown_id bigserial NOT NULL,
    machine_id bigint NOT NULL,
    fault_code character varying(50) COLLATE pg_catalog."default",
    fault_description text COLLATE pg_catalog."default",
    fault_category character varying(50) COLLATE pg_catalog."default",
    severity_level character varying(30) COLLATE pg_catalog."default",
    breakdown_start_time timestamp without time zone NOT NULL,
    breakdown_end_time timestamp without time zone,
    downtime_minutes numeric(10, 2),
    breakdown_status character varying(30) COLLATE pg_catalog."default" DEFAULT 'Open'::character varying,
    reported_by character varying(100) COLLATE pg_catalog."default",
    technician_id bigint,
    technician_name character varying(150) COLLATE pg_catalog."default",
    root_cause text COLLATE pg_catalog."default",
    corrective_action text COLLATE pg_catalog."default",
    preventive_action text COLLATE pg_catalog."default",
    spare_parts_used text COLLATE pg_catalog."default",
    repair_cost numeric(10, 2),
    resolved_date timestamp without time zone,
    remarks text COLLATE pg_catalog."default",
    created_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    created_by character varying(50) COLLATE pg_catalog."default",
    is_active boolean DEFAULT true,
    CONSTRAINT trn_machine_breakdown_pkey PRIMARY KEY (breakdown_id)
);

COMMENT ON TABLE press_db.trn_machine_breakdown
    IS 'Stores machine fault and breakdown records';

COMMENT ON COLUMN press_db.trn_machine_breakdown.breakdown_id
    IS 'Primary key for machine breakdown record';

COMMENT ON COLUMN press_db.trn_machine_breakdown.machine_id
    IS 'Reference to machine where breakdown occurred';

COMMENT ON COLUMN press_db.trn_machine_breakdown.fault_code
    IS 'Unique code identifying the fault type';

COMMENT ON COLUMN press_db.trn_machine_breakdown.fault_description
    IS 'Detailed description of the fault';

COMMENT ON COLUMN press_db.trn_machine_breakdown.fault_category
    IS 'Fault category (Mechanical, Electrical, Software, Operator Error)';

COMMENT ON COLUMN press_db.trn_machine_breakdown.severity_level
    IS 'Severity level of breakdown (Low, Medium, High, Critical)';

COMMENT ON COLUMN press_db.trn_machine_breakdown.breakdown_start_time
    IS 'Timestamp when machine breakdown started';

COMMENT ON COLUMN press_db.trn_machine_breakdown.breakdown_end_time
    IS 'Timestamp when breakdown ended';

COMMENT ON COLUMN press_db.trn_machine_breakdown.downtime_minutes
    IS 'Total downtime in minutes caused by breakdown';

COMMENT ON COLUMN press_db.trn_machine_breakdown.breakdown_status
    IS 'Current breakdown status (Open, Assigned, In Progress, Resolved, Closed)';

COMMENT ON COLUMN press_db.trn_machine_breakdown.reported_by
    IS 'Name or ID of person who reported the breakdown';

COMMENT ON COLUMN press_db.trn_machine_breakdown.technician_id
    IS 'Reference to technician assigned to fix the issue';

COMMENT ON COLUMN press_db.trn_machine_breakdown.technician_name
    IS 'Name of technician handling the repair';

COMMENT ON COLUMN press_db.trn_machine_breakdown.root_cause
    IS 'Root cause identified after analysis';

COMMENT ON COLUMN press_db.trn_machine_breakdown.corrective_action
    IS 'Action taken to fix the breakdown';

COMMENT ON COLUMN press_db.trn_machine_breakdown.preventive_action
    IS 'Preventive steps taken to avoid recurrence';

COMMENT ON COLUMN press_db.trn_machine_breakdown.spare_parts_used
    IS 'List of spare parts used during repair';

COMMENT ON COLUMN press_db.trn_machine_breakdown.repair_cost
    IS 'Total repair cost incurred';

COMMENT ON COLUMN press_db.trn_machine_breakdown.resolved_date
    IS 'Date when issue was resolved';

COMMENT ON COLUMN press_db.trn_machine_breakdown.remarks
    IS 'Additional notes related to breakdown';

COMMENT ON COLUMN press_db.trn_machine_breakdown.created_on
    IS 'Record creation timestamp';

COMMENT ON COLUMN press_db.trn_machine_breakdown.created_by
    IS 'User who created the breakdown record';

COMMENT ON COLUMN press_db.trn_machine_breakdown.is_active
    IS 'Indicates whether breakdown record is active';

CREATE TABLE IF NOT EXISTS press_db.trn_notification
(
    notification_id bigserial NOT NULL,
    notification_no character varying(30) COLLATE pg_catalog."default",
    template_id integer,
    channel character varying(20) COLLATE pg_catalog."default" NOT NULL,
    module character varying(50) COLLATE pg_catalog."default" NOT NULL,
    event_type character varying(50) COLLATE pg_catalog."default" NOT NULL,
    reference_id integer,
    reference_no character varying(50) COLLATE pg_catalog."default",
    recipient_type character varying(30) COLLATE pg_catalog."default" NOT NULL,
    recipient_user_id bigint,
    recipient_party_id integer,
    recipient_name character varying(150) COLLATE pg_catalog."default",
    recipient_email character varying(150) COLLATE pg_catalog."default",
    recipient_mobile character varying(20) COLLATE pg_catalog."default",
    recipient_whatsapp character varying(20) COLLATE pg_catalog."default",
    subject character varying(500) COLLATE pg_catalog."default",
    body text COLLATE pg_catalog."default" NOT NULL,
    body_format character varying(20) COLLATE pg_catalog."default" DEFAULT 'HTML'::character varying,
    priority character varying(20) COLLATE pg_catalog."default" DEFAULT 'NORMAL'::character varying,
    status character varying(30) COLLATE pg_catalog."default" DEFAULT 'QUEUED'::character varying,
    retry_count integer DEFAULT 0,
    max_retries integer DEFAULT 3,
    scheduled_at timestamp without time zone,
    sent_at timestamp without time zone,
    delivered_at timestamp without time zone,
    read_at timestamp without time zone,
