    external_ref_id character varying(100) COLLATE pg_catalog."default",
    provider_name character varying(50) COLLATE pg_catalog."default",
    provider_response text COLLATE pg_catalog."default",
    attachments_json jsonb,
    metadata_json jsonb,
    ai_generated boolean DEFAULT false,
    ai_personalized boolean DEFAULT false,
    ai_summary text COLLATE pg_catalog."default",
    created_on timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT trn_notification_pkey PRIMARY KEY (notification_id)
);

