    activity_data jsonb DEFAULT '{}'::jsonb,
    related_entity_type character varying(100) COLLATE pg_catalog."default",
    related_entity_id bigint,
    related_entity_code character varying(100) COLLATE pg_catalog."default",
    job_id bigint,
    process_id integer,
    subprocess_id integer,
    ip_address character varying(50) COLLATE pg_catalog."default",
    user_agent character varying(500) COLLATE pg_catalog."default",
