    REFERENCES press_db.mst_transaction_type (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;


ALTER TABLE IF EXISTS press_db.trn_tds_ledger
    ADD CONSTRAINT fk_tds_company FOREIGN KEY (company_id)
    REFERENCES press_db.mst_company (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;
CREATE INDEX IF NOT EXISTS idx_tds_company
    ON press_db.trn_tds_ledger(company_id);


ALTER TABLE IF EXISTS press_db.trn_tds_ledger
    ADD CONSTRAINT fk_tds_party FOREIGN KEY (party_id)
    REFERENCES press_db.mst_party (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;
CREATE INDEX IF NOT EXISTS idx_tds_party
    ON press_db.trn_tds_ledger(party_id);


ALTER TABLE IF EXISTS press_db.trn_user_notification
    ADD CONSTRAINT fk_user_notif_notification FOREIGN KEY (notification_id)
    REFERENCES press_db.trn_notification (notification_id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_user_notif_notif
    ON press_db.trn_user_notification(notification_id);


ALTER TABLE IF EXISTS press_db.trn_user_notification
    ADD CONSTRAINT fk_user_notif_user FOREIGN KEY (user_id)
    REFERENCES press_db.mst_user (userid) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_user_notif_user
    ON press_db.trn_user_notification(user_id);


ALTER TABLE IF EXISTS press_db.user_login_log
    ADD CONSTRAINT fk_login_log_user FOREIGN KEY (userid)
    REFERENCES press_db.mst_user (userid) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_login_log_user
    ON press_db.user_login_log(userid);

END;